from pathlib import Path

content = Path("MIGRATION.md").read_text(encoding="utf-8")
lines = content.split("\n")


def heading_positions(lines):
    out = []
    for i, raw in enumerate(lines):
        m = re.match(r"^(#{1,6})\s+(.*)$", raw)
        if m:
            out.append((i, len(m.group(1)), m.group(2).strip().lower()))
    return out


def code_block_starts(lines):
    starts, inside = [], False
    for i, raw in enumerate(lines):
        if re.match(r"^\s*```", raw):
            if not inside:
                starts.append(i)
            inside = not inside
    return starts


def topic_ok(lines, code_starts, needles):
    needles_lower = [n.lower() for n in needles]
    mention_lines = []
    for i, raw in enumerate(lines):
        low = raw.lower()
        if all(n in low for n in needles_lower):
            mention_lines.append(i)
    if not mention_lines:
        for needle in needles_lower:
            for i, raw in enumerate(lines):
                if needle in raw.lower():
                    mention_lines.append(i)
                    break
    if not mention_lines:
        return False, False
    proximate = any(abs(s - m) <= 8 for s in code_starts for m in mention_lines)
    return True, proximate


headings = heading_positions(lines)
code_starts = code_block_starts(lines)
words = len(content.split())
print(f"headings={len(headings)} levels={len({l for _, l, _ in headings})}")
print(f"words={words}")
print(f"code_blocks={len(code_starts)}")

topics = {
    "auth_header": ("authorization", "bearer"),
    "uuid_id": ("uuid",),
    "field_rename": ("completed", "done"),
    "project_id_and_v2": ("project_id", "/v2"),
}
results = {}
for name, needles in topics.items():
    mentioned, proximate = topic_ok(lines, code_starts, needles)
    results[name] = (mentioned, proximate)
    print(f"{name}: mentioned={mentioned} proximate={proximate}")

final_third = max(1, len(lines) * 2 // 3)
tail = "\n".join(lines[final_third:])
has_checklist = bool(
    re.search(r"^\s*-\s*\[", tail, re.MULTILINE)
    or re.search(r"^\s*\d+\.\s", tail, re.MULTILINE)
)
has_upgrade = bool(
    re.search(
        r"pip\s+install\s+(?:--upgrade|-U)\b"
        r"|pip\s+upgrade\b"
        r"|pip\s+install\s+\S+\s*[><~=]=?"
        r"|pipx\s+(?:install|upgrade)\b"
        r"|uv\s+pip\s+install\b"
        r"|poetry\s+(?:add|update)\b",
        tail,
        re.IGNORECASE,
    )
)
print(f"final_third: checklist={has_checklist} upgrade={has_upgrade}")

score = sum(
    [
        len({l for _, l, _ in headings}) >= 2 and len(headings) >= 3,
        words >= 400,
        len(code_starts) >= 3,
        *(1 for (m, p) in results.values() if m and p),
        has_checklist and has_upgrade,
    ]
)
print(f"score={score}/8")
